create table if not exists invoices(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),customer_id uuid references customers(id),order_id uuid references orders(id),invoice_no text not null,invoice_date date not null default current_date,subtotal numeric(14,2) default 0,cgst numeric(14,2) default 0,sgst numeric(14,2) default 0,igst numeric(14,2) default 0,total numeric(14,2) default 0,status text default 'open',created_at timestamptz default now(),unique(tenant_id,invoice_no));
create table if not exists collections(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),customer_id uuid references customers(id),invoice_id uuid references invoices(id),amount numeric(14,2) not null,payment_mode text not null,reference_no text,received_at timestamptz default now(),created_at timestamptz default now());
create table if not exists ledger_accounts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),code text not null,name text not null,account_type text not null,unique(tenant_id,code));
create table if not exists journal_entries(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),reference_type text,reference_id uuid,entry_date date default current_date,memo text,created_at timestamptz default now());
create table if not exists journal_lines(id uuid primary key default gen_random_uuid(),journal_id uuid not null references journal_entries(id) on delete cascade,account_id uuid not null references ledger_accounts(id),debit numeric(14,2) default 0,credit numeric(14,2) default 0);
